(() => {
  const levels = window.ARTHSETU_LEVELS || [];
  const $ = (s, root=document) => root.querySelector(s);
  const app = $('#app');
  const storeKey = 'arthsetu-household-v2';
  let savedState={}; try{savedState=JSON.parse(localStorage.getItem(storeKey)||'{}')||{};}catch(_e){}
  const state = Object.assign({lang:'en',active:null,tab:'podcast',safe:false,search:'',quiz:{},done:[],bookmarks:[],notes:{}}, savedState); if(state.lang!=='hi')state.lang='en';
  const save = () => { try{localStorage.setItem(storeKey, JSON.stringify(state));}catch(_e){} };
  const escapeHTML = s => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const isHi = () => state.lang === 'hi';
  const t = (en, hi) => isHi() ? (hi || en) : (en || hi);
  const levelTitle = l => `${l.hi} <span class="title-en">${escapeHTML(l.title)}</span>`;
  const countDone = () => state.done.length;
  const allCards = () => levels.flatMap(l => [...l.basics,...l.build,...l.advanced].map(c=>({l,c})));
  const cardKey = (lid, c) => `${lid}:${c.title}`;
  const statusPct = () => Math.round((countDone()/Math.max(1,allCards().length))*100);
  const levelPct = l => {
    const cards=[...l.basics,...l.build,...l.advanced];
    return Math.round(cards.filter(c=>state.done.includes(cardKey(l.id,c))).length/cards.length*100);
  };
  const sourcesHTML = l => `<div class="sources"><b>${t('Official sources to verify','आधिकारिक स्रोत')}</b>${(l.sources||[]).map(s=>`<a href="${s[1]}" target="_blank" rel="noopener">${escapeHTML(s[0])} ↗</a>`).join('')}</div>`;
  const header = () => `<header class="topbar">
    <a class="brand" href="#home" data-action="home"><span class="brand-mark"><img src="assets/bull-logo.png" alt="ArthSetu bull logo"></span><span>ARTH<span class="brand-light">SETU</span><small>HOUSEHOLD MODE · घर-परिवार</small></span></a>
    <nav class="nav-links"><button data-action="backcategories">${t('← All categories','← सभी श्रेणियाँ')}</button><button data-action="home">${t('Journey','यात्रा')}</button><button data-action="checklist">${t('Household checklist','परिवार चेकलिस्ट')}</button><button data-action="bookmarks">${t('Saved lessons','सहेजे पाठ')} (${state.bookmarks.length})</button></nav>
    <div class="top-actions"><label class="lang-switch"><select id="language"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="hi" ${state.lang==='hi'?'selected':''}>हिन्दी</option></select></label><button class="safe-top ${state.safe?'active':''}" data-action="safe">${state.safe?'● ':''}${t('Safe Mode','सेफ मोड')}</button></div>
  </header>`;
  const footer = () => `<footer class="footer"><div class="footer-brand"><img class="footer-logo" src="assets/bull-logo.png" alt="ArthSetu bull logo"><span><b>ARTHSETU · घर • परिवार • भविष्य</b><span>${t('Learn together. Grow together.','साथ सीखें, साथ आगे बढ़ें।')}</span></span></div><p>${t('Educational content, not personalised financial, tax or legal advice. Rates, limits and rules change. Verify with RBI, SEBI, Income Tax Department, India Post, IRDAI and the relevant scheme/provider before relying on any figure.','यह शैक्षिक सामग्री है, व्यक्तिगत वित्तीय, कर या कानूनी सलाह नहीं। दरें, सीमाएँ और नियम बदलते हैं। किसी भी जानकारी पर निर्भर करने से पहले RBI, SEBI, आयकर विभाग, India Post, IRDAI और संबंधित संस्था से पुष्टि करें।')}</p></footer>`;
  const progressBar = () => `<div class="progress-card"><div class="progress-head"><span>${t('YOUR HOUSEHOLD JOURNEY','आपके परिवार की यात्रा')}</span><b>${countDone()} <small>/ ${allCards().length} ${t('lesson cards done','पाठ पूरे')}</small></b></div><div class="progress-track"><i style="width:${statusPct()}%"></i></div><small>${statusPct()}% ${t('of learning cards completed','सीखने के कार्ड पूरे हुए')} · ${levels.filter(l=>levelPct(l)===100).length}/9 ${t('levels fully complete','स्तर पूरे')}</small></div>`;
  const renderHome = () => {
    state.active=null; state.tab='podcast';
    const heroImage='assets/old-bazaar.jpg';
    app.innerHTML = `${header()}<main id="home">
      <section class="hero hero-home"><img class="hero-photo" src="${heroImage}" alt="Indian textile bazaar with traditional craft"><div class="hero-shade"></div><div class="hero-copy"><div class="eyebrow">✦ ${t('A HOUSEHOLD LEARNING JOURNEY','परिवार के साथ सीखने की यात्रा')}</div><h1>${t('Money conversations,\nstronger families.','पैसों की समझ,\nपरिवार की मजबूती।').replace('\n','<br>')}<br><em>${t('One small step at a time.','एक-एक कदम साथ।')}</em></h1><p>${t('A warm, practical guide for Indian households—from the first money conversation to retirement and legacy. Learn in English, हिन्दी or Hinglish.','भारतीय परिवारों के लिए सरल और व्यावहारिक गाइड—पहली पैसों की बातचीत से रिटायरमेंट और विरासत तक। English, हिन्दी या Hinglish में सीखें।')}</p><a class="hero-cta" href="#journey">${t('Explore the nine levels','नौ स्तर देखें')} <span>↓</span></a></div><div class="hero-note"><span>01 — 09</span><span>${t('NINE STEPS · ONE SHARED FUTURE','नौ कदम · साझा भविष्य')}</span></div></section>${state.safe?`<div class="safe-ribbon"><b>♡ ${t('SAFE MODE IS ON','सेफ मोड चालू है')}</b><span>${t('Private learning is available; joint sessions are not required.','निजी सीख उपलब्ध है; संयुक्त बैठक जरूरी नहीं।')}</span><button data-action="safeopen">${t('Open Safe Mode support','सेफ मोड सहायता खोलें')}</button></div>`:''}
      <section class="intro" id="journey"><div><div class="eyebrow muted">${t('THE HOUSEHOLD COLLECTION','परिवार की सीख')}</div><h2>${t('Small steps.','छोटे कदम।')} <em>${t('Stronger roots.','मज़बूत नींव।')}</em></h2><p>${t('Start with the basics. Build habits that most families can use. Open advanced lessons when your income, assets or responsibilities become more complex. You can explore every level freely; the recommended path follows a household’s money journey.','बुनियाद से शुरुआत करें। ऐसी आदतें बनाएँ जो अधिकतर परिवार अपना सकें। आय, संपत्ति या जिम्मेदारियाँ बढ़ें तो उन्नत पाठ खोलें। सभी स्तर खुले हैं; सुझाया क्रम परिवार की वित्तीय यात्रा के अनुसार है।')}</p><div class="depth-legend"><span><i class="dot basic"></i><b>Basic</b> · ${t('every household','हर परिवार')}</span><span><i class="dot build"></i><b>Build</b> · ${t('most families','अधिकतर परिवार')}</span><span><i class="dot advanced"></i><b>Advanced</b> · ${t('as complexity grows','जटिलता बढ़ने पर')}</span></div></div>${progressBar()}</section>
      <section class="levels-section"><div class="section-head"><div><div class="eyebrow muted">${t('NINE CHAPTERS','नौ अध्याय')}</div><h2>${t('Choose your','अपना')} <em>${t('next step.','अगला कदम चुनें।')}</em></h2></div><div class="search-tools"><input id="search" type="search" value="${escapeHTML(state.search)}" placeholder="${t('Search any topic…','कोई विषय खोजें…')}" aria-label="Search lessons"></div></div>
      <div class="level-grid" id="level-grid">${levels.map(l=>levelCard(l)).join('')}</div>
      <div class="legend-note">${t('Recommended order is 1 → 9, but every chapter can be opened at any time. Your progress is saved on this device.','सुझाया क्रम 1 → 9 है, पर हर अध्याय कभी भी खोल सकते हैं। आपकी प्रगति इसी डिवाइस पर सुरक्षित रहती है।')}</div></section>
      <section class="feature-band"><div class="feature-copy"><div class="eyebrow">${t('MADE FOR REAL LIFE','असली जीवन के लिए')}</div><h2>${t('Money feels lighter when','पैसे का बोझ हल्का लगता है जब')}<br><em>${t('you carry it together.','आप साथ मिलकर चलते हैं।')}</em></h2><p>${t('Stories, simple tools and small conversations—not a lecture.','कहानियाँ, आसान टूल और छोटी बातचीत—लंबा भाषण नहीं।')}</p></div><img src="assets/tea-conversation.jpg" alt="A tea seller and customer share a conversation"></section>
      <section class="quick-links"><button data-action="checklist"><span>✓</span><b>${t('Household checklist','परिवार चेकलिस्ट')}</b><small>${t('What should both adults know?','दोनों वयस्कों को क्या पता होना चाहिए?')}</small></button><button data-action="safe"><span>♡</span><b>${t('Private learning / Safe Mode','निजी सीख / सेफ मोड')}</b><small>${t('Learn without requiring a joint session.','संयुक्त बैठक के बिना सीखें।')}</small></button><button data-action="templates"><span>▤</span><b>${t('Printable worksheets','प्रिंट करने योग्य वर्कशीट')}</b><small>${t('Money Map, decision log and goal sheet.','मनी मैप, निर्णय लॉग और लक्ष्य शीट।')}</small></button></section>
    </main>${footer()}`;
    $('#search')?.addEventListener('input',e=>{state.search=e.target.value;save();filterLevels(e.target.value)});
    $('#language').addEventListener('change',e=>{state.lang=e.target.value;save();renderHome()});
  };
  function levelCard(l){return `<button class="level-card" data-level="${l.id}" style="--accent:${l.accent}"><span class="card-top"><span>CHAPTER ${String(l.id).padStart(2,'0')}</span><span>${levelPct(l)}%</span></span><span class="card-photo"><img src="${l.image}" alt=""></span><span class="card-title">${escapeHTML(l.title)}</span><span class="card-sub">${escapeHTML(l.hi)} · ${escapeHTML(l.en)}</span><span class="card-bottom"><span>${t('EXPLORE CHAPTER','अध्याय खोलें')}</span><span class="card-arrow">↗</span></span></button>`;}
  function filterLevels(q){const term=q.toLowerCase();$('#level-grid').innerHTML=levels.filter(l=>{const searchable=[l.title,l.hi,l.en,l.intro,...l.basics,...l.build,...l.advanced].map(x=>typeof x==='string'?x:Object.values(x).join(' ')).join(' ').toLowerCase();return searchable.includes(term)}).map(levelCard).join('')||`<p class="empty-state">${t('No matching lesson found. Try another word.','कोई पाठ नहीं मिला। दूसरा शब्द खोजें।')}</p>`;}
  const openLevel = id => {state.active=Number(id);state.tab='podcast';renderLevel();window.scrollTo({top:0,behavior:'smooth'});};
  const tabs=[['podcast','◖','Podcast / कहानी'],['basic','01','Basic / बुनियाद'],['build','02','Build / आदतें'],['advanced','03','Advanced / आगे'],['flows','⇢','Flowcharts / रास्ते'],['quiz','?','Quiz / जाँच'],['lines','✦','Three colour lines / तीन रंग']];
  function tabBar(){return `<div class="lesson-tabs" role="tablist">${tabs.map(([id,ic,label])=>`<button role="tab" aria-selected="${state.tab===id}" class="${state.tab===id?'active':''}" data-tab="${id}"><i>${ic}</i><span>${label}</span></button>`).join('')}</div>`;}
  function lessonCard(l,c,depth){
    const key=cardKey(l.id,c),done=state.done.includes(key),book=state.bookmarks.includes(key),note=state.notes[key]||'';
    return `<article class="lesson-card ${done?'is-done':''}" data-card="${escapeHTML(key)}"><div class="lesson-card-head"><div><span class="depth-pill ${depth.toLowerCase()}">${depth}</span><h3>${escapeHTML(t(c.title,c.hi))}</h3><small>${escapeHTML(t(c.hi,c.title))}</small></div><div class="card-actions"><button class="bookmark-btn ${book?'saved':''}" data-book="${escapeHTML(key)}" title="${t('Save lesson','पाठ सहेजें')}">${book?'★':'☆'}</button><span class="expand-mark">＋</span></div></div><div class="lesson-card-body">
      <div class="explain-grid"><div><b>${t('WHAT IT IS','यह क्या है')}</b><p>${escapeHTML(t(c.what,c.whatHi))}</p></div><div><b>${t('WHY IT MATTERS','यह क्यों ज़रूरी है')}</b><p>${escapeHTML(t(c.why,c.whyHi))}</p></div></div>
      <div class="how-box"><b>${t('HOW TO DO IT','कैसे करें')}</b><div>${(isHi()?c.howHi:c.how).split(/\n|(?<=\.)\s+(?=\d\.)/).filter(Boolean).map((x,i)=>`<p><i>${i+1}</i>${escapeHTML(x.replace(/^\d+\.\s*/,''))}</p>`).join('')}</div></div>
      <div class="example-box"><b>₹ ${t('ILLUSTRATION ONLY','केवल उदाहरण')}</b><p>${escapeHTML(t(c.example,c.exampleHi))}</p></div>
      <div class="mistake-row"><span>⚠ ${t('COMMON MISTAKE','आम गलती')}</span><p>${escapeHTML(t(c.mistake,c.mistakeHi))}</p></div>
      <div class="check-row"><span>✓ ${t('CHECK YOURSELF','खुद जाँचें')}</span><p>${escapeHTML(t(c.check,c.checkHi))}</p></div>
      <label class="note-label">${t('Your private note (optional)','आपका निजी नोट (वैकल्पिक)')}<textarea data-note="${escapeHTML(key)}" placeholder="${t('Write a reminder for yourself…','अपने लिए याद रखने वाली बात लिखें…')}">${escapeHTML(note)}</textarea></label>
      <div class="lesson-foot"><label><input type="checkbox" data-done="${escapeHTML(key)}" ${done?'checked':''}> ${t('Mark this lesson done','यह पाठ पूरा हुआ')}</label><button class="text-button" data-book="${escapeHTML(key)}">${book?t('Remove bookmark','बुकमार्क हटाएँ'):t('Save for later','बाद में पढ़ें')}</button></div>
    </div></article>`;
  }
  function podcastSection(l){return `<section class="lesson-panel podcast-panel"><div class="panel-heading"><div><div class="eyebrow muted">${t('THE FAMILY STORY','परिवार की कहानी')} · ${t('AUDIO EPISODE','ऑडियो एपिसोड')}</div><h2>${t('A conversation at home','घर की एक बातचीत')}</h2><p>${escapeHTML(t(l.intro,l.introHi))}</p></div><div class="audio-doodle">♫</div></div><div class="podcast-player"><div class="player-art"><img src="${l.image}" alt=""></div><div class="player-info"><span class="depth-pill">${t('A SHORT AUDIO-STYLE EPISODE','छोटा पॉडकास्ट एपिसोड')}</span><h3>${escapeHTML(t(l.title,l.hi))}</h3><p>${t('Listen to the family discuss a real-life money moment. You can read along or use your device’s text-to-speech.','परिवार की असली जिंदगी से जुड़ी पैसों की बातचीत सुनें। साथ पढ़ें या डिवाइस का टेक्स्ट-टू-स्पीच इस्तेमाल करें।')}</p><div class="player-controls"><button class="gold-button" data-action="readpodcast">▶ ${t('Read aloud','आवाज़ में सुनें')}</button><button class="outline-button" data-action="stoppodcast">■ ${t('Stop','रोकें')}</button><label>${t('Speed','गति')} <select id="speech-rate"><option value="0.85">0.85×</option><option value="1" selected>1×</option><option value="1.15">1.15×</option></select></label></div><small class="subtle">${t('Voice availability depends on your browser and device. The full transcript is always available below.','आवाज़ की सुविधा आपके ब्राउज़र और डिवाइस पर निर्भर है। पूरा संवाद नीचे पढ़ सकते हैं।')}</small></div></div>
      <div class="chapter-list"><span>${t('EPISODE CHAPTERS','एपिसोड के हिस्से')}</span><a href="#episode-transcript">01 · ${t('The moment','घटना')}</a><a href="#lesson-area" data-tab="basic">02 · Basic</a><a href="#lesson-area" data-tab="build">03 · Build</a><a href="#lesson-area" data-tab="advanced">04 · Advanced</a><a href="#lesson-area" data-tab="lines">05 · ${t('Takeaway','सीख')}</a></div>
      <div class="transcript" id="episode-transcript">${l.podcast.map((p,i)=>`<div class="dialogue"><div class="avatar avatar-${p.who.toLowerCase()}">${p.who[0]}</div><div><small>${p.who}</small><p>${escapeHTML(t(p.en,p.hi))}</p>${state.lang==='hinglish'?`<p class="secondary-line">${escapeHTML(p.hi)}</p>`:''}</div></div>`).join('')}</div>
      <div class="recap"><b>${t('AAJ HUMNE SEEKHA · WHAT WE LEARNED','आज हमने सीखा')}</b><ol><li>${t('See the whole household picture.','घर की पूरी वित्तीय तस्वीर देखें।')}</li><li>${t('Choose the next action together and write it down.','अगला कदम मिलकर चुनें और लिखें।')}</li><li>${t('Review calmly; no blame, no shame.','शांति से समीक्षा करें; दोष या शर्म नहीं।')}</li></ol></div>
    </section>`;}
  function sectionCards(l,kind){const arr=l[kind];const dep=kind==='basics'?'Basic':kind==='build'?'Build':'Advanced';return `<section class="lesson-panel"><div class="panel-heading"><div><div class="eyebrow muted">${dep.toUpperCase()} · ${kind==='basics'?t('EVERY HOUSEHOLD','हर परिवार'):kind==='build'?t('MOST FAMILIES','अधिकतर परिवार'):t('AS COMPLEXITY GROWS','जटिलता बढ़ने पर')}</div><h2>${kind==='basics'?t('Start with the essentials','ज़रूरी बातों से शुरुआत'):kind==='build'?t('Build a repeatable habit','काम की आदतें बनाएँ'):t('Advanced: read when it applies to you','उन्नत: जब यह आप पर लागू हो तब पढ़ें')}</h2><p>${kind==='basics'?t('Action-first steps for every household.','हर परिवार के लिए सीधे काम आने वाले कदम।'):kind==='build'?t('Turn the basics into a household system.','बुनियादी बातों को घरेलू व्यवस्था में बदलें।'):t('More complex choices may need professional advice.','जटिल फैसलों में विशेषज्ञ सलाह की ज़रूरत हो सकती है।')}</p></div></div>${arr.map(c=>lessonCard(l,c,dep)).join('')}${kind==='basics'&&l.id===2?accountTable():''}${kind==='build'&&l.id===3?budgetExamples():''}${kind==='build'&&l.id===4?emiCalculator():''}${kind==='basics'&&l.id===1?levelOneTools():''}${kind==='basics'&&l.id===4?loanTypesTable():''}${kind==='advanced'&&l.id===4?liabilityTable():''}${kind==='build'&&l.id===5?coverCompareTable():''}${kind==='basics'&&l.id===6?investmentCompareTable():''}${kind==='build'&&l.id===7?homeCostTable():''}${kind==='build'&&l.id===8?taxCompareTable():''}${kind==='build'&&l.id===9?retirementCompareTable():''}${sourcesHTML(l)}</section>`;}
  function flowSection(l){return `<section class="lesson-panel"><div class="panel-heading"><div><div class="eyebrow muted">${t('SEE THE DECISION','निर्णय को समझें')}</div><h2>${t('A simple path through the question','सवाल से फैसले तक आसान रास्ता')}</h2><p>${t('Follow the steps in order. A red flag means pause and verify—not rush.','कदमों को क्रम से देखें। खतरे का संकेत हो तो रुकें और जाँचें—जल्दबाज़ी न करें।')}</p></div></div><div class="flow-grid">${l.flows.map((f,i)=>`<article class="flow-card"><div class="flow-title"><span>0${i+1}</span><h3>${escapeHTML(t(f.title,f.hi))}</h3></div><div class="flow-nodes">${f.steps.map((s,j)=>`<div class="flow-node"><i>${j+1}</i><span>${escapeHTML(s)}</span></div>${j<f.steps.length-1?'<div class="flow-arrow">↓</div>':''}`).join('')}</div></article>`).join('')}</div></section>`;}
  function quizSection(l){const qState=state.quiz[l.id]||{index:0,answers:[]};const index=Math.min(qState.index,l.quiz.length-1),q=l.quiz[index],chosen=qState.answers[index];const opts=state.lang==='hi'?(q.optsHi||q.opts):q.opts;const score=qState.answers.filter((a,i)=>a===l.quiz[i].a).length;return `<section class="lesson-panel quiz-panel"><div class="panel-heading"><div><div class="eyebrow muted">${t('CHECK WHAT STUCK','कितना याद रहा')}</div><h2>${t('A five-question family check','पाँच सवालों की छोटी जाँच')}</h2><p>${t('Try on your own first. The explanation appears after you choose.','पहले खुद जवाब दें। विकल्प चुनने के बाद समझाया जाएगा।')}</p></div><div class="quiz-score"><b>${score}/${l.quiz.length}</b><small>${t('correct so far','अब तक सही')}</small></div></div><div class="quiz-progress">${l.quiz.map((_,i)=>`<i class="${i<qState.answers.length?'done':''} ${i===index?'current':''}"></i>`).join('')}</div><div class="quiz-box"><div class="quiz-kicker">${t('QUESTION','प्रश्न')} ${index+1} / ${l.quiz.length}</div><h3>${escapeHTML(t(q.q,q.hi))}</h3><div class="quiz-options">${opts.map((o,i)=>`<button class="quiz-option ${chosen!==undefined?(i===q.a?'correct':i===chosen?'incorrect':''):''}" data-answer="${i}" ${chosen!==undefined?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${escapeHTML(o)}</button>`).join('')}</div>${chosen!==undefined?`<div class="quiz-feedback ${chosen===q.a?'good':'bad'}"><b>${chosen===q.a?t('That’s right!','बिल्कुल सही!'):t('Not quite—here is why.','थोड़ा अलग—कारण समझें।')}</b><p>${escapeHTML(t(q.why,q.whyHi))}</p></div>`:''}<div class="quiz-actions">${chosen!==undefined&&index<l.quiz.length-1?`<button class="gold-button" data-action="nextq">${t('Next question','अगला सवाल')} →</button>`:''}${qState.answers.length===l.quiz.length?`<button class="outline-button" data-action="resetquiz">${t('Try again','फिर से करें')}</button><span>${t('Quiz completed','क्विज़ पूरा हुआ')} · ${score}/${l.quiz.length}</span>`:''}</div></div></section>`;}
  function levelOneTools(){return `<div class="toolkit-wrap"><div class="toolkit-heading"><div class="eyebrow muted">${t('LEVEL 1 HOUSEHOLD TOOLKIT','स्तर 1 · परिवार के टूल')}</div><h2>${t('Make the conversation practical.','बातचीत को काम में बदलें।')}</h2><p>${t('Use sample details only. This worksheet does not need real account numbers, PAN, Aadhaar, passwords or OTPs.','केवल उदाहरण भरें। इस वर्कशीट में असली खाता नंबर, PAN, Aadhaar, पासवर्ड या OTP की जरूरत नहीं है।')}</p></div>
  <div class="tool-grid"><article class="tool-card wide"><div class="tool-number">01</div><h3>${t('A one-page Money Map','एक पन्ने का मनी मैप')}</h3><p>${t('Write the household picture—not credentials.','घर की वित्तीय तस्वीर लिखें—लॉगिन जानकारी नहीं।')}</p><div class="worksheet-grid"><label>${t('Income source and monthly amount','आय का स्रोत और मासिक रकम')}<input placeholder="e.g. Salary · ₹45,000"></label><label>${t('Other / irregular income','अन्य / अनियमित आय')}<input placeholder="e.g. Shop · average range"></label><label>${t('Fixed monthly costs','निश्चित मासिक खर्च')}<input placeholder="e.g. Rent, school, EMI"></label><label>${t('Variable monthly costs','बदलते मासिक खर्च')}<input placeholder="e.g. Food, travel, power"></label><label>${t('Loans and due dates','लोन और देय तारीख')}<input placeholder="Lender name · EMI · due date"></label><label>${t('Policies and renewal dates','पॉलिसी और नवीनीकरण तारीख')}<input placeholder="Insurer · policy type · due month"></label><label>${t('Accounts and nominees','खाते और नॉमिनी')}<input placeholder="Bank name · account type · nominee"></label><label>${t('Who knows / where records are','किसे पता है / रिकॉर्ड कहाँ हैं')}<input placeholder="Person · safe document location"></label></div><div class="tool-actions"><button class="gold-button" data-action="printmoney">${t('Print Money Map','मनी मैप प्रिंट करें')} ↗</button><small>${t('Keep sensitive credentials in a secure place separately.','गुप्त लॉगिन जानकारी अलग सुरक्षित रखें।')}</small></div></article>
  <article class="tool-card"><div class="tool-number">02</div><h3>${t('Needs or wants? 15-card sort','ज़रूरत या चाहत? 15 चीज़ें')}</h3><p>${t('Tap a label for each item. Context matters: an item may be essential for one family and optional for another.','हर चीज़ के लिए एक श्रेणी चुनें। परिस्थिति मायने रखती है—एक के लिए जरूरी, दूसरे के लिए वैकल्पिक।')}</p><div class="sort-list" id="needs-sort">${['Monthly ration / groceries','Essential medicines','School transport','Rent or home EMI','Festival sweets and décor','New phone while old one works','Two-wheeler fuel for work','Streaming subscription','Basic home repair','Wedding gift','Emergency travel to hospital','Restaurant delivery','Work clothes / uniform','Holiday upgrade','Child’s exam fee'].map((x,i)=>`<div class="sort-item"><span>${i+1}. ${x}</span><select aria-label="Classify ${x}"><option value="">${t('Choose','चुनें')}</option><option value="Need">${t('Need','ज़रूरत')}</option><option value="Want">${t('Want','चाहत')}</option><option value="Goal / planned">${t('Goal / planned','लक्ष्य / योजना')}</option></select></div>`).join('')}</div><div class="tool-actions"><button class="outline-button" data-action="sortsummary">${t('Review my sort','मेरी सूची देखें')}</button><span id="sort-result" class="tool-result"></span></div></article>
  <article class="tool-card"><div class="tool-number">03</div><h3>${t('Choose 2–3 shared goals','2–3 साझा लक्ष्य चुनें')}</h3><p>${t('A goal needs an amount, date and a small next action.','लक्ष्य के लिए रकम, तारीख और अगला छोटा कदम तय करें।')}</p><div class="goal-fields"><label>${t('Goal 1','लक्ष्य 1')}<input placeholder="e.g. Emergency fund"></label><label>${t('Target amount (₹)','लक्ष्य रकम (₹)')}<input type="number" min="0" placeholder="e.g. 30000"></label><label>${t('Months to target','लक्ष्य तक महीने')}<input type="number" min="1" placeholder="e.g. 12"></label><div class="computed" id="goal-monthly">₹ — <small>${t('per month','प्रति माह')}</small></div></div><div class="sample-goals"><b>${t('Example family goals','उदाहरण पारिवारिक लक्ष्य')}</b><span>${t('Emergency fund · one week of essential costs','आपातकालीन फंड · एक सप्ताह का जरूरी खर्च')}</span><span>${t('Child’s school · next fee date and amount','बच्चे की स्कूल फीस · अगली तारीख और रकम')}</span><span>${t('Home repair · quote, month and set-aside','घर की मरम्मत · अनुमान, महीना और बचत')}</span></div><button class="outline-button" data-action="goalcalc">${t('Calculate monthly amount','मासिक बचत निकालें')}</button></article>
  <article class="tool-card wide"><div class="tool-number">04</div><h3>${t('30-minute monthly meeting','30 मिनट की मासिक बैठक')}</h3><p>${t('A simple 5–10–10–5 rhythm. Keep it calm and finish on time.','5–10–10–5 मिनट का आसान क्रम। शांति से बात करें और समय पर समाप्त करें।')}</p><div class="meeting-timeline"><div><b>05 min</b><span>${t('Wins and changes','अच्छी बातें और बदलाव')}</span></div><div><b>10 min</b><span>${t('Income, expenses and bills','आय, खर्च और बिल')}</span></div><div><b>10 min</b><span>${t('Goals and decisions','लक्ष्य और फैसले')}</span></div><div><b>05 min</b><span>${t('Owners and next date','जिम्मेदारी और अगली तारीख')}</span></div></div><label class="single-label">${t('Next meeting date','अगली बैठक की तारीख')}<input type="date"></label></article>
  <article class="tool-card"><div class="tool-number">05</div><h3>${t('CFO of the month rotation','महीने के CFO की बारी')}</h3><p>${t('Rotate coordination, not control. Both people retain independent access and say.','समन्वय की बारी बदलें, नियंत्रण नहीं। दोनों की स्वतंत्र पहुँच और राय बनी रहे।')}</p><div class="rotation-table"><div><b>${t('Month','महीना')}</b><b>${t('Meeting lead','बैठक संचालक')}</b></div>${['January','February','March','April','May','June'].map((m,i)=>`<div><span>${t(m,['जनवरी','फरवरी','मार्च','अप्रैल','मई','जून'][i])}</span><input placeholder="${i%2===0?'Rohan / Priya':'Priya / Rohan'}"></div>`).join('')}</div></article>
  <article class="tool-card"><div class="tool-number">06</div><h3>${t('Decision log · sample limit ₹5,000','निर्णय लॉग · उदाहरण सीमा ₹5,000')}</h3><p>${t('Agree a threshold that fits your household; ₹5,000 is only an example.','अपने घर के अनुसार सीमा तय करें; ₹5,000 केवल उदाहरण है।')}</p><div class="decision-row"><span>${t('Date','तारीख')}</span><span>${t('Purchase','खरीद')}</span><span>${t('Amount','रकम')}</span></div><div class="decision-row"><span>12/06</span><span>${t('Mixer repair vs replace','मिक्सर मरम्मत या नया')}</span><span>₹5,800</span></div><div class="decision-row"><span>12/06</span><span>${t('Compare two options','दो विकल्प तुलना')}</span><span>${t('Discussed','चर्चा')}</span></div><label class="single-label">${t('Your next decision to log','अगला निर्णय')}<input placeholder="What · why · cost · agreed by whom"></label></article>
  <article class="tool-card wide"><div class="tool-number">07</div><h3>${t('Three ways to organise family money','पारिवारिक पैसे की तीन व्यवस्थाएँ')}</h3><div class="comparison-grid"><div><b>${t('All joint','सब संयुक्त')}</b><p>${t('One shared pool. Simple visibility and joint decisions; less personal privacy and needs clear spending rules.','एक साझा राशि। पारदर्शिता और संयुक्त फैसले आसान; निजी स्वतंत्रता कम और खर्च के स्पष्ट नियम जरूरी।')}</p></div><div><b>${t('All separate','सब अलग')}</b><p>${t('Each adult manages their own money. More autonomy; shared bills, unequal income and care work need careful coordination.','हर वयस्क अपना पैसा संभाले। स्वतंत्रता अधिक; साझा बिल, अलग आय और देखभाल के काम का समन्वय जरूरी।')}</p></div><div><b>${t('Hybrid: yours, mine, ours','मिश्रित: तुम्हारा, मेरा, हमारा')}</b><p>${t('A shared contribution account plus personal accounts. Balances shared duties and autonomy; agree fair contributions and access.','साझा खर्च/लक्ष्य के लिए एक राशि और निजी खाते। जिम्मेदारी और स्वतंत्रता का संतुलन; योगदान के न्यायसंगत नियम तय करें।')}</p></div></div></article>
  <article class="tool-card wide"><div class="tool-number">08</div><h3>${t('Disclosure checklist: talk without blame','वित्तीय जानकारी: बिना दोष के बात')}</h3><div class="check-grid">${['Loans and credit-card balances','Assets and property interests','Dependants and caregiving','Parent / sibling support','Guarantees or co-borrower roles','Past credit issues or defaults','Business obligations and tax dues','Existing policies and nominees'].map(x=>`<label><input type="checkbox"> ${t(x, x)}</label>`).join('')}</div><div class="conversation-tip"><b>${t('A helpful opening line','बात शुरू करने का तरीका')}</b><p>${t('“I want us to have the same information so we can plan safely. Let’s understand the numbers, not judge each other.”','“मैं चाहता/चाहती हूँ कि हम दोनों के पास एक जैसी जानकारी हो, ताकि सुरक्षित योजना बना सकें। आइए रकम समझें, एक-दूसरे को जज न करें।”')}</p></div></article></div></div>`;}
  function accountTable(){return `<div class="reference-table-wrap"><h3>${t('Account types: what to ask the bank','खाते के प्रकार: बैंक से क्या पूछें')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Account','खाता')}</th><th>${t('Often useful for','किसके लिए')}</th><th>${t('Balance, interest and charges','बैलेंस, ब्याज और शुल्क')}</th><th>${t('Documents / trade-off','दस्तावेज़ / सावधानी')}</th></tr></thead><tbody>${[
 ['Savings','Personal money','Minimum balance and interest vary by bank / variant; check charges','KYC documents; easy access for daily needs'],
 ['Salary','Salary credits','May have salary-linked waiver; check what happens after salary stops','KYC and employer arrangement; may convert to regular savings'],
 ['BSBD / Jan Dhan / zero-balance','Basic banking / eligible customers','No minimum balance under the basic product; service / transaction conditions apply','KYC; check debit-card and additional-service conditions'],
 ['Current','Business receipts and payments','Often no savings interest; minimum balance / charges may be higher','Business KYC; overdraft is a separate credit facility'],
 ['Minor','Child under guardian operation','Product-specific balance and transaction rules','Guardian KYC; rules change when child becomes an adult'],
 ['Joint','Shared household money','Charges / interest follow the selected product','All holders KYC; operating mandate must be clear'],
 ['Senior citizen','Older account holder','Any special rate/benefit is bank-specific; verify current terms','KYC; accessibility and trusted alerts are useful'],
 ['NRE / NRO','Eligible non-resident Indians','Tax, interest and repatriation treatment differ','Residency and overseas documents; get bank guidance'],
 ['Small finance / payments bank','Digital, local or basic banking use','Products, limits and services differ; check deposit insurance and fees','KYC; payments banks have a narrower lending scope']
 ].map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="table-note">${t('Minimum balance, interest, charges, KYC documents and limits change by institution and account variant. Ask for the current schedule of charges and a written product sheet.','न्यूनतम बैलेंस, ब्याज, शुल्क, KYC दस्तावेज़ और सीमाएँ संस्था/खाते के अनुसार बदलती हैं। मौजूदा शुल्क सूची और लिखित जानकारी माँगें।')}</p></div>`;}
  function budgetExamples(){return `<div class="reference-table-wrap"><h3>${t('Illustrative household budget templates','उदाहरण के घरेलू बजट')}</h3><p class="table-note">${t('These are teaching examples, not recommended allocations. Change them to fit city, rent, dependants, health and debt.','ये सीखने के उदाहरण हैं, सुझाया बजट नहीं। शहर, किराया, आश्रित, स्वास्थ्य और कर्ज़ के अनुसार बदलें।')}</p><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Monthly take-home','मासिक हाथ में आय')}</th><th>${t('Essentials','जरूरत')}</th><th>${t('Bills / debt','बिल / कर्ज़')}</th><th>${t('Savings / goals','बचत / लक्ष्य')}</th><th>${t('Flexible / annual','लचीला / सालाना')}</th></tr></thead><tbody>${[['₹30,000','₹16,000','₹5,000','₹3,000','₹6,000'],['₹60,000','₹28,000','₹12,000','₹8,000','₹7,000 + ₹5,000'],['₹1,20,000','₹48,000','₹24,000','₹24,000','₹12,000 + ₹12,000']].map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
  function emiCalculator(){return `<div class="reference-table-wrap"><h3>${t('Try a simple EMI estimate','EMI का अनुमान लगाएँ')}</h3><div class="calculator-grid"><label>${t('Loan amount (₹)','लोन रकम (₹)')}<input type="number" id="emi-principal" value="500000" min="0"></label><label>${t('Annual interest (%)','सालाना ब्याज (%)')}<input type="number" id="emi-rate" value="10" min="0" step="0.1"></label><label>${t('Term (years)','अवधि (साल)')}<input type="number" id="emi-years" value="5" min="1"></label><button class="gold-button" data-action="emicalc">${t('Estimate EMI','EMI निकालें')}</button><div class="computed" id="emi-result">₹ — <small>${t('monthly EMI · illustration only','मासिक EMI · केवल उदाहरण')}</small></div></div><small class="table-note">${t('Estimate only. Actual lender EMI depends on reducing-balance terms, fees, disbursement dates and contract details.','केवल अनुमान। असली EMI घटते मूलधन, शुल्क, वितरण तारीख और अनुबंध पर निर्भर है।')}</small></div>`;}
  function loanTypesTable(){return `<div class="reference-table-wrap"><h3>${t('Common borrowing options','आम उधार विकल्प')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Type','प्रकार')}</th><th>${t('May suit','कब उपयोगी')}</th><th>${t('Questions before borrowing','उधार से पहले सवाल')}</th></tr></thead><tbody>${[
 ['Home loan','Buying a home','Floating / fixed rate, down payment, title, total interest, prepayment terms'],['Vehicle loan','Vehicle for work or mobility','Depreciation, insurance, maintenance and repossession terms'],['Education loan','Eligible study costs','Moratorium, interest during study, co-borrower and repayment after course'],['Personal loan','Unavoidable planned need','Usually unsecured and can be costly; compare APR and total repayment'],['Gold loan','Short-term borrowing against pledged gold','Valuation, auction/default rules, loan-to-value and renewal'],['Credit card / BNPL','Short purchase convenience only if repaid promptly','APR, late fees, billing cycle, auto-debit and consequences of minimum-only payment'],['Microfinance / SHG / chit','Community / small business finance where lawful and suitable','Lender / group rules, total charges, collection conduct, registration and written records']
 ].map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="table-note">${t('Products differ by lender and borrower. Check lender regulation, written terms and total annualised cost.','ऋणदाता और उधारकर्ता के अनुसार शर्तें अलग होती हैं। ऋणदाता का पंजीकरण, लिखित शर्तें और कुल सालाना लागत देखें।')}</p></div>`;}
  function liabilityTable(){return `<div class="reference-table-wrap"><h3>${t('Co-borrower vs guarantor','सह-उधारकर्ता और गारंटर')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Role','भूमिका')}</th><th>${t('What it usually means','आम तौर पर अर्थ')}</th><th>${t('What to check','क्या जाँचें')}</th></tr></thead><tbody><tr><td>Co-borrower</td><td>${t('A party to the loan who shares contractual repayment responsibility.','लोन का पक्षकार, जिस पर अनुबंध के अनुसार भुगतान की जिम्मेदारी हो सकती है।')}</td><td>${t('Repayment clauses, ownership share, credit reporting and default terms.','भुगतान शर्तें, स्वामित्व हिस्सा, क्रेडिट रिपोर्ट और डिफॉल्ट नियम।')}</td></tr><tr><td>Guarantor</td><td>${t('Promises to meet specified obligations if borrower defaults, as per guarantee contract.','गारंटी अनुबंध के अनुसार उधारकर्ता के डिफॉल्ट पर तय दायित्व निभाने का वादा।')}</td><td>${t('Guarantee scope, limit, duration, release conditions and lender rights.','गारंटी का दायरा, सीमा, अवधि, समाप्ति शर्तें और ऋणदाता के अधिकार।')}</td></tr></tbody></table></div><p class="table-note">${t('Liability depends on the signed agreement and applicable law. Obtain independent advice before guaranteeing another person’s debt.','जिम्मेदारी हस्ताक्षरित अनुबंध और लागू कानून पर निर्भर है। किसी और के कर्ज़ की गारंटी से पहले स्वतंत्र सलाह लें।')}</p></div>`;}
  function coverCompareTable(){return `<div class="reference-table-wrap"><h3>${t('Health-cover structures at a glance','हेल्थ कवर के तरीके')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Structure','प्रकार')}</th><th>${t('How it works','कैसे काम करता है')}</th><th>${t('Trade-off to check','किस बात की जाँच')}</th></tr></thead><tbody><tr><td>Individual</td><td>${t('Separate sum insured for each covered person.','हर सदस्य के लिए अलग बीमित राशि।')}</td><td>${t('Can cost more; each person has dedicated cover.','लागत अधिक हो सकती है; हर व्यक्ति का कवर अलग।')}</td></tr><tr><td>Family floater</td><td>${t('One shared sum insured among covered members.','कवर सदस्यों के बीच एक साझा राशि।')}</td><td>${t('One large claim can reduce what remains for others.','एक बड़ा क्लेम बाकी सदस्यों के लिए बची राशि घटा सकता है।')}</td></tr><tr><td>Super top-up</td><td>${t('Pays eligible expenses above an aggregate deductible, subject to terms.','कुल deductible से ऊपर पात्र खर्च, शर्तों के अनुसार।')}</td><td>${t('Check deductible, exclusions and coordination with base cover.','Deductible, exclusions और बेस कवर का समन्वय जाँचें।')}</td></tr></tbody></table></div><p class="table-note">${t('Do not compare premium alone. Compare exclusions, waiting periods, room limits, co-pay and claim experience.','केवल प्रीमियम की तुलना न करें। अपवाद, प्रतीक्षा अवधि, कमरे की सीमा, co-pay और क्लेम प्रक्रिया देखें।')}</p></div>`;}
  function investmentCompareTable(){return `<div class="reference-table-wrap"><h3>${t('Savings and investment comparison','बचत और निवेश की तुलना')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Option','विकल्प')}</th><th>${t('Typical purpose','आम उद्देश्य')}</th><th>${t('Liquidity / risk / checks','नकदी / जोखिम / जाँच')}</th></tr></thead><tbody>${[
 ['RD / FD','Planned saving and known time horizon','Bank terms, premature penalty, tax and DICGC eligibility'],['PPF','Long-term small savings','Long lock-in, annual rules, loan/withdrawal and current rate'],['Post Office schemes / SCSS','Small savings / eligible senior citizens','Eligibility, tenure, quarterly rates and withdrawal conditions'],['Mutual funds / SIP','Market-linked goals','Riskometer, fund category, costs, exit load and no assured return'],['Gold: jewellery / ETF / digital','Diversification or cultural use','Making charge / spread, market price, custody and legal structure'],['Real estate','Housing or concentrated long-term asset','Stamp duty, registration, maintenance, liquidity and loan burden']
 ].map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="table-note">${t('Rates, tax, scheme features and eligibility must be checked on the official provider’s current page.','दरें, टैक्स, योजना की सुविधाएँ और पात्रता आधिकारिक संस्था के मौजूदा पेज पर देखें।')}</p></div>`;}
  function homeCostTable(){return `<div class="reference-table-wrap"><h3>${t('Home-buying cost checklist','घर खरीदने की लागत सूची')}</h3><div class="check-grid">${['Down payment','Stamp duty and registration','Loan processing / legal / valuation fees','Repairs, furnishing and moving','Monthly maintenance and property tax','Loan EMI and rate-reset risk','Emergency fund still intact','Independent title / approval check'].map(x=>`<label><input type="checkbox"> ${t(x,({'Down payment':'डाउन पेमेंट','Stamp duty and registration':'स्टाम्प ड्यूटी और रजिस्ट्रेशन','Repairs, furnishing and moving':'मरम्मत, फर्निशिंग और शिफ्टिंग','Emergency fund still intact':'आपातकालीन फंड सुरक्षित'}[x]||x))}</label>`).join('')}</div></div>`;}
  function taxCompareTable(){return `<div class="reference-table-wrap"><h3>${t('Tax documents: what each one tells you','टैक्स दस्तावेज़ क्या बताते हैं')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>Document</th><th>${t('What it generally shows','आम तौर पर क्या दिखाता है')}</th><th>${t('What to compare it with','किससे मिलाएँ')}</th></tr></thead><tbody><tr><td>Form 16</td><td>${t('Employer salary and TDS details.','नियोक्ता से वेतन और TDS की जानकारी।')}</td><td>${t('Salary slips, bank credits and deductions.','वेतन पर्ची, बैंक क्रेडिट और कटौतियाँ।')}</td></tr><tr><td>AIS</td><td>${t('Broader information reported to the tax department.','कर विभाग को रिपोर्ट की गई व्यापक जानकारी।')}</td><td>${t('Bank interest, broker statements and own records.','बैंक ब्याज, ब्रोकर स्टेटमेंट और अपने रिकॉर्ड।')}</td></tr><tr><td>Form 26AS</td><td>${t('Tax-credit statement and specified tax information.','टैक्स क्रेडिट स्टेटमेंट और निर्दिष्ट जानकारी।')}</td><td>${t('TDS certificates and tax payment receipts.','TDS प्रमाणपत्र और कर भुगतान रसीदें।')}</td></tr><tr><td>ITR acknowledgement</td><td>${t('Proof that a return was filed; not by itself proof that every item is correct.','रिटर्न दाखिल होने का प्रमाण; अपने आप में हर विवरण सही होने का प्रमाण नहीं।')}</td><td>${t('Filed return, computation and supporting documents.','दाखिल रिटर्न, गणना और सहायक दस्तावेज़।')}</td></tr></tbody></table></div></div>`;}
  function retirementCompareTable(){return `<div class="reference-table-wrap"><h3>${t('Retirement income approaches','रिटायरमेंट आय के तरीके')}</h3><div class="table-scroll"><table class="reference-table"><thead><tr><th>${t('Approach','तरीका')}</th><th>${t('What it does','क्या करता है')}</th><th>${t('Key trade-off','मुख्य सावधानी')}</th></tr></thead><tbody><tr><td>SWP</td><td>${t('Withdraws a planned amount from an investment portfolio.','निवेश पोर्टफोलियो से तय रकम निकालता है।')}</td><td>${t('Market fall and withdrawals can deplete units; not interest.','बाजार गिरावट और निकासी यूनिट घटा सकती है; यह ब्याज नहीं।')}</td></tr><tr><td>Annuity</td><td>${t('Converts a lump sum into contract-based periodic income.','एकमुश्त रकम को अनुबंध आधारित नियमित आय में बदलता है।')}</td><td>${t('Liquidity, inflation protection and survivor benefit vary by option.','नकदी, महँगाई सुरक्षा और survivor benefit विकल्प पर निर्भर।')}</td></tr><tr><td>Bucket strategy</td><td>${t('Separates near-term cash needs from longer-term assets.','निकट अवधि के नकद और लंबी अवधि की संपत्ति अलग करता है।')}</td><td>${t('Needs regular refill, rebalancing and risk review.','नियमित भराई, रीबैलेंसिंग और जोखिम समीक्षा चाहिए।')}</td></tr></tbody></table></div></div>`;}
  function linesSection(l){
    const checks=(state.greenDone||{})[l.id]||[];
    return `<section class="lesson-panel lines-panel"><div class="panel-heading"><div><div class="eyebrow muted">${t('THE THREE COLOUR LINES','तीन रंग की सीख')}</div><h2>${t('What we keep, do and review','क्या जानें, क्या करें और क्या जाँचें')}</h2><p>${t('Every level closes with three practical reminders.','हर स्तर का अंत तीन काम की बातों से होता है।')}</p></div></div>
    <article class="colour-line green-line"><div class="line-icon">✓</div><div class="line-body"><span class="line-label">${t('GREEN · BOTH MUST KNOW','हरा · दोनों को पता होना चाहिए')}</span><h3>${t(l.both,l.bothHi)}</h3><p>${t('Tick the checks as your household becomes confident.','परिवार को जानकारी हो जाए तो बॉक्स पर निशान लगाएँ।')}</p><div class="green-checks">${[t('Both adults can find the relevant records.','दोनों वयस्क संबंधित रिकॉर्ड ढूँढ सकते हैं।'),t('Nominee / responsibility information is reviewed.','नॉमिनी / जिम्मेदारी की जानकारी जाँची गई है।'),t('No one has to share passwords or PINs to complete this check.','यह जाँच पूरी करने के लिए पासवर्ड/PIN साझा करने की जरूरत नहीं।')].map((x,i)=>`<label><input type="checkbox" data-green="${l.id}" data-index="${i}" ${checks.includes(i)?'checked':''}> ${x}</label>`).join('')}</div></div></article>
    <article class="colour-line blue-line"><div class="line-icon">↗</div><div class="line-body"><span class="line-label">${t('BLUE · DO TOGETHER','नीला · साथ मिलकर करें')}</span><h3>${state.safe?t('Private learning activity','निजी सीख की गतिविधि'):escapeHTML(t(l.activity,l.activityHi))}</h3><p>${state.safe?t('Safe Mode is on. Skip joint sessions and do this privately, at your own pace.','सेफ मोड चालू है। संयुक्त बैठक छोड़ें और अपनी गति से निजी तौर पर सीखें।'):t('One shared action is more useful than a perfect plan that never starts.','एक साझा कदम उस परफेक्ट योजना से बेहतर है जो कभी शुरू ही न हो।')}</p>${state.safe?`<div class="safe-private-task">${t('Private option: write down what information you need, where it may be held and one safe person or professional who can help. Do not confront anyone if that could increase risk.','निजी विकल्प: लिखें कि कौन-सी जानकारी चाहिए, कहाँ हो सकती है और कौन-सा सुरक्षित व्यक्ति/विशेषज्ञ मदद कर सकता है। यदि जोखिम बढ़ सकता हो तो किसी का सामना न करें।')}</div>`:`<button class="gold-button" data-action="startactivity">${t('Start activity','गतिविधि शुरू करें')} →</button><button class="outline-button" data-action="printactivity">${t('Print activity sheet','गतिविधि शीट प्रिंट करें')}</button>`}<label class="done-activity"><input type="checkbox" data-activity="${l.id}" ${(state.activities||[]).includes(l.id)?'checked':''}> ${t('We did it','हमने पूरा किया')}</label></div></article>
    <article class="colour-line amber-line"><div class="line-icon">!</div><div class="line-body"><span class="line-label">${t('AMBER · UPDATE NOTE','अंबर · अपडेट नोट')}</span><h3>${escapeHTML(t(l.update,l.updateHi))}</h3><p>${t('Last reviewed: November 2026 · Verify current rules before taking action.','अंतिम समीक्षा: नवंबर 2026 · कदम उठाने से पहले मौजूदा नियम देखें।')}</p>${sourcesHTML(l)}</div></article>
    ${l.id===1?`<div class="safe-callout"><div><b>🛑 ${t('SAFE MODE · YOUR SAFETY COMES FIRST','सेफ मोड · आपकी सुरक्षा सबसे पहले')}</b><p>${escapeHTML(t(l.update,l.updateHi))} ${t('Private learning and independent support are valid options. You do not need to attend a joint money session.','निजी सीख और स्वतंत्र सहायता सही विकल्प हैं। आपको संयुक्त पैसों की बैठक में शामिल होना जरूरी नहीं।')}</p></div><div class="source-pills"><a href="https://112.gov.in/" target="_blank" rel="noopener">112 · ${t('Emergency','आपातकाल')}</a><a href="https://www.wcd.gov.in/one-stop-centre-scheme" target="_blank" rel="noopener">${t('One Stop Centre support','वन स्टॉप सेंटर सहायता')}</a><a href="https://cybercrime.gov.in/" target="_blank" rel="noopener">1930 / ${t('Cyber fraud','साइबर धोखाधड़ी')}</a></div></div>`:''}
    </section>`;
  }
  function renderLevel(){
    const l=levels.find(x=>x.id===state.active); if(!l){renderHome();return;}
    let content=state.tab==='podcast'?podcastSection(l):state.tab==='basic'?sectionCards(l,'basics'):state.tab==='build'?sectionCards(l,'build'):state.tab==='advanced'?sectionCards(l,'advanced'):state.tab==='flows'?flowSection(l):state.tab==='quiz'?quizSection(l):linesSection(l);
    app.innerHTML=`${header()}<main class="lesson-page">
      <div class="breadcrumb"><button data-action="home">← ${t('All levels','सभी स्तर')}</button><span> / ${t('Household mode','परिवार मोड')} / ${t('Level','स्तर')} ${l.id}</span></div>
      ${state.safe?`<div class="safe-ribbon"><b>♡ ${t('SAFE MODE IS ON','सेफ मोड चालू है')}</b><span>${t('Private learning only. Joint activities are optional and hidden.','केवल निजी सीख। संयुक्त गतिविधियाँ वैकल्पिक हैं और छिपी हैं।')}</span><button data-action="safe">${t('Turn off','बंद करें')}</button></div>`:''}
      <section class="chapter-hero" style="--accent:${l.accent}"><img src="${l.image}" alt=""><div class="chapter-hero-shade"></div><div class="chapter-hero-copy"><div class="eyebrow">LEVEL ${String(l.id).padStart(2,'0')} / 09 · ${escapeHTML(l.tag.toUpperCase())}</div><h1>${escapeHTML(l.title)}<br><em>${escapeHTML(l.hi)} · ${escapeHTML(l.en)}</em></h1><p>${escapeHTML(t(l.intro,l.introHi))}</p><div class="chapter-progress"><span>${t('YOUR PROGRESS','आपकी प्रगति')}</span><b>${levelPct(l)}%</b><i><u style="width:${levelPct(l)}%"></u></i></div></div><div class="chapter-number">${String(l.id).padStart(2,'0')}</div></section>
      ${tabBar()}<div id="lesson-area">${content}</div>
      <div class="chapter-bottom-nav"><button class="outline-button" data-action="home">← ${t('Back to journey','यात्रा पर वापस')}</button>${l.id<9?`<button class="gold-button" data-level="${l.id+1}">${t('Next level','अगला स्तर')} →</button>`:''}</div>
    </main>${footer()}`;
    $('#language').addEventListener('change',e=>{state.lang=e.target.value;save();renderLevel()});
    bindLevelInputs();
  }
  function safePage(){
    state.active=null;
    app.innerHTML=`${header()}<main class="utility-page"><div class="eyebrow muted">${t('PRIVATE LEARNING SPACE','निजी सीख का स्थान')}</div><h1>${t('Your safety comes first.','आपकी सुरक्षा सबसे पहले।')}</h1><p class="utility-intro">${t('If money is being used to control, threaten or isolate you, a joint money meeting may not be safe. You can learn privately, keep your own notes and contact a trusted service. Do not confront anyone if it could increase danger.','यदि पैसों का इस्तेमाल आपको नियंत्रित करने, धमकाने या अलग-थलग करने के लिए हो रहा है, तो संयुक्त बैठक सुरक्षित नहीं हो सकती। आप निजी तौर पर सीख सकते हैं, अपने नोट रख सकते हैं और भरोसेमंद सहायता से संपर्क कर सकते हैं। यदि खतरा बढ़ सकता हो तो किसी का सामना न करें।')}</p><div class="safe-service-grid"><a href="https://112.gov.in/" target="_blank" rel="noopener"><b>112</b><span>${t('Emergency response in immediate danger','तत्काल खतरे में आपातकालीन सहायता')}</span><small>112.gov.in ↗</small></a><a href="https://www.wcd.gov.in/one-stop-centre-scheme" target="_blank" rel="noopener"><b>${t('One Stop Centre','वन स्टॉप सेंटर')}</b><span>${t('Support for women affected by violence, including counselling and legal / medical referral as available','हिंसा से प्रभावित महिलाओं के लिए परामर्श और उपलब्ध कानूनी/चिकित्सा सहायता से जोड़ना')}</span><small>wcd.gov.in ↗</small></a><a href="https://cybercrime.gov.in/" target="_blank" rel="noopener"><b>1930</b><span>${t('Report financial cyber fraud quickly','वित्तीय साइबर धोखाधड़ी की शीघ्र रिपोर्ट')}</span><small>cybercrime.gov.in ↗</small></a></div><div class="safe-private-task"><h3>${t('A private next step','निजी अगला कदम')}</h3><ol><li>${t('Use a device and email account that are safe for you.','ऐसा डिवाइस और ईमेल इस्तेमाल करें जो आपके लिए सुरक्षित हो।')}</li><li>${t('Avoid saving notes where another person can access them.','ऐसी जगह नोट न रखें जहाँ दूसरा व्यक्ति पहुँच सके।')}</li><li>${t('Speak with a trusted person or an authorised support service.','किसी भरोसेमंद व्यक्ति या अधिकृत सहायता सेवा से बात करें।')}</li><li>${t('If immediate danger exists, seek emergency help.','तत्काल खतरा हो तो आपात सहायता लें।')}</li></ol></div><button class="gold-button" data-action="home">${t('Return to private lessons','निजी पाठों पर लौटें')}</button></main>${footer()}`;
    $('#language').addEventListener('change',e=>{state.lang=e.target.value;save();safePage()});
  }
  function checklistPage(){
    const done=state.greenDoneAll||[];
    app.innerHTML=`${header()}<main class="utility-page"><div class="eyebrow muted">${t('HOUSEHOLD CHECKLIST','परिवार चेकलिस्ट')}</div><h1>${t('What should both adults know?','दोनों वयस्कों को क्या पता होना चाहिए?')}</h1><p class="utility-intro">${t('A practical index of the green-line checks across the nine levels. Complete what applies to your family; not every product or legal arrangement is relevant to every household.','नौ स्तरों की हरी लाइन की जाँच का एक व्यावहारिक संग्रह। जो आपके परिवार पर लागू हो वही पूरा करें; हर उत्पाद हर घर के लिए जरूरी नहीं।')}</p>${levels.map(l=>`<article class="checklist-level"><div><span>LEVEL ${l.id}</span><h3>${escapeHTML(t(l.hi,l.title))}</h3><small>${escapeHTML(l.en)}</small></div><p>${escapeHTML(t(l.bothHi,l.both))}</p><label><input type="checkbox" data-allgreen="${l.id}" ${done.includes(l.id)?'checked':''}> ${t('We know this / reviewed it','हमें यह जानकारी है / समीक्षा की')}</label></article>`).join('')}<div class="utility-actions"><button class="gold-button" data-action="printchecklist">${t('Print household checklist','परिवार चेकलिस्ट प्रिंट करें')}</button><button class="outline-button" data-action="home">${t('Back to levels','स्तरों पर वापस')}</button></div></main>${footer()}`;
    $('#language').addEventListener('change',e=>{state.lang=e.target.value;save();checklistPage()});
  }
  function bookmarksPage(){
    const saved=allCards().filter(({l,c})=>state.bookmarks.includes(cardKey(l.id,c)));
    app.innerHTML=`${header()}<main class="utility-page"><div class="eyebrow muted">${t('YOUR READING LIST','आपकी पढ़ने की सूची')}</div><h1>${t('Saved lessons','सहेजे पाठ')}</h1><p class="utility-intro">${t('Keep useful lessons close and return when your household is ready.','काम के पाठ सहेजें और जरूरत पड़ने पर लौटें।')}</p>${saved.length?saved.map(({l,c})=>`<button class="saved-row" data-open-card="${l.id}" data-card-title="${escapeHTML(c.title)}"><span>LEVEL ${l.id}</span><b>${escapeHTML(t(c.title,c.hi))}</b><small>${escapeHTML(l.title)}</small><i>↗</i></button>`).join(''):`<p class="empty-state">${t('No saved lessons yet. Open a chapter and tap the star on a lesson card.','अभी कोई पाठ सहेजा नहीं है। अध्याय खोलें और पाठ कार्ड पर स्टार दबाएँ।')}</p>`}<button class="outline-button" data-action="home">${t('Back to levels','स्तरों पर वापस')}</button></main>${footer()}`;
    $('#language').addEventListener('change',e=>{state.lang=e.target.value;save();bookmarksPage()});
  }
  function templatesPage(){app.innerHTML=`${header()}<main class="utility-page"><div class="eyebrow muted">${t('PRINTABLE WORKSHEETS','प्रिंट वर्कशीट')}</div><h1>${t('A little paper can help.','कागज़ पर लिखना भी मददगार है।')}</h1><p class="utility-intro">${t('Print blank templates and fill them in offline. Do not include credentials or sensitive identification numbers.','खाली टेम्पलेट प्रिंट करें और ऑफलाइन भरें। पासवर्ड या संवेदनशील पहचान संख्या न लिखें।')}</p><div class="template-grid">${[['Money Map','मनी मैप','Eight fields: income, expenses, loans, policies, accounts and document location.'],['Decision Log','निर्णय लॉग','Date, purchase, amount, alternatives, decision and review date.'],['Goal Timeline','लक्ष्य समयरेखा','Goal, current cost, target year, monthly amount and priority.'],['If I am gone','अगर मैं न रहूँ','Institutions, record locations, nominee and trusted contacts.']].map(x=>`<article><b>${t(x[1],x[0])}</b><p>${t(x[2],x[2])}</p><button class="gold-button" data-print-template="${x[0]}">${t('Print','प्रिंट करें')} ↗</button></article>`).join('')}</div><button class="outline-button" data-action="home">${t('Back to levels','स्तरों पर वापस')}</button></main>${footer()}`;$('#language').addEventListener('change',e=>{state.lang=e.target.value;save();templatesPage()});}
  function bindLevelInputs(){
    app.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',e=>{state.notes[e.target.dataset.note]=e.target.value;save()}));
  }
  function showActivity(l){
    const text=state.safe?t('Private option: Write down the information you need and identify a safe support person. Do not take any step that increases your risk.','निजी विकल्प: जरूरी जानकारी लिखें और सुरक्षित सहायता व्यक्ति पहचानें। जोखिम बढ़ाने वाला कदम न उठाएँ।'):t(l.activity,l.activityHi);
    const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<section class="activity-modal"><button class="close" data-close-modal>✕</button><div class="eyebrow muted">LEVEL ${l.id} · ${t('TRY IT NOW','अभी अभ्यास करें')}</div><h2>${t('Your next small step','आपका अगला छोटा कदम')}</h2><p>${escapeHTML(text)}</p><ul><li>${t('Set aside 10–20 quiet minutes.','10–20 मिनट का शांत समय चुनें।')}</li><li>${t('Use estimates or sample numbers; never share credentials.','अनुमान या उदाहरण संख्या लें; लॉगिन जानकारी कभी साझा न करें।')}</li><li>${t('Write one action and a review date.','एक कदम और समीक्षा की तारीख लिखें।')}</li></ul><button class="gold-button" data-close-modal>${t('I have a next step','मेरा अगला कदम तय है')} ✓</button></section>`;app.appendChild(overlay);overlay.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>overlay.remove()));
  }
  function printHTML(title,body){
    const printRoot=$('#print-root');printRoot.innerHTML=`<div class="print-sheet"><header><strong>अर्थसेतु · ARTHSETU</strong><span>HOUSEHOLD MODE</span></header><h1>${escapeHTML(title)}</h1>${body}<p class="print-disclaimer">Educational worksheet · Illustration only · Do not write passwords, OTPs, PINs, PAN, Aadhaar or full account numbers here.</p></div>`;
    window.print();
  }
  function printMoneyMap(){
    const fields=[...app.querySelectorAll('.worksheet-grid input')];const labels=[...app.querySelectorAll('.worksheet-grid label')].map(l=>l.childNodes[0].textContent.trim());
    const rows=fields.map((f,i)=>`<tr><th>${escapeHTML(labels[i]||'')}</th><td>${escapeHTML(f.value||'')}</td></tr>`).join('');
    printHTML('Money Map / पैसों का नक्शा',`<table><tbody>${rows}</tbody></table><p><b>Reminder:</b> Store credentials separately in a secure place.</p>`);
  }
  function printActivity(l){printHTML(`Level ${l.id}: ${l.title}`,`<p>${escapeHTML(l.activity)}</p><h3>Steps</h3><ol><li>Set a quiet time.</li><li>Use estimates or dummy information.</li><li>Agree one next action and a review date.</li></ol><p>Notes: ______________________________________________________________</p><p>_____________________________________________________________________</p>`);}
  function doAction(action){
    if(action==='backcategories'){ if(window.parent!==window){window.parent.postMessage({type:'ARTHSETU_BACK_TO_CATEGORIES'},location.origin);} return; }
    if(action==='home'){state.active=null;save();renderHome();window.scrollTo(0,0);}
    else if(action==='checklist'){checklistPage();window.scrollTo(0,0);}
    else if(action==='bookmarks'){bookmarksPage();window.scrollTo(0,0);}
    else if(action==='templates'){templatesPage();window.scrollTo(0,0);}
    else if(action==='safeopen'){state.safe=true;save();safePage();window.scrollTo(0,0);}
    else if(action==='safe'){state.safe=!state.safe;save();if(state.safe){safePage();}else{state.active?renderLevel():renderHome();}window.scrollTo(0,0);}
    
    else if(action==='readpodcast'){
      const l=levels.find(x=>x.id===state.active);if(!l)return;
      if(!('speechSynthesis'in window)){alert(t('Text-to-speech is not available in this browser. Please read the transcript below.','इस ब्राउज़र में आवाज़ की सुविधा उपलब्ध नहीं है। नीचे संवाद पढ़ें।'));return;}
      speechSynthesis.cancel();const rate=Number($('#speech-rate')?.value||1);const txt=l.podcast.map(p=>`${p.who}. ${t(p.en,p.hi)}`).join('. ');const u=new SpeechSynthesisUtterance(txt);u.lang=state.lang==='hi'?'hi-IN':'en-IN';u.rate=rate;speechSynthesis.speak(u);
    }
    else if(action==='stoppodcast'){if('speechSynthesis'in window)speechSynthesis.cancel();}
    else if(action==='nextq'){const l=levels.find(x=>x.id===state.active);const qs=state.quiz[l.id];qs.index=Math.min(l.quiz.length-1,qs.index+1);save();renderLevel();}
    else if(action==='resetquiz'){const l=levels.find(x=>x.id===state.active);state.quiz[l.id]={index:0,answers:[]};save();renderLevel();}
    else if(action==='sortsummary'){
      const selects=[...$('#needs-sort').querySelectorAll('select')];const counts={'Need':0,'Want':0,'Goal / planned':0};selects.forEach(s=>{if(s.value in counts)counts[s.value]++});$('#sort-result').textContent=`${t('Sorted','वर्गीकृत')}: ${counts.Need} ${t('needs','ज़रूरतें')}, ${counts.Want} ${t('wants','चाहतें')}, ${counts['Goal / planned']} ${t('goals','लक्ष्य')}.`;
    }
    else if(action==='goalcalc'){
      const amounts=[...$('.goal-fields').querySelectorAll('input')];const amount=Number(amounts[1].value),months=Number(amounts[2].value);$('#goal-monthly').innerHTML=amount>0&&months>0?`₹ ${Math.ceil(amount/months).toLocaleString('en-IN')} <small>${t('per month','प्रति माह')} · ${t('before returns','रिटर्न से पहले')}</small>`:`₹ — <small>${t('enter amount and months','रकम और महीने भरें')}</small>`;
    }
    else if(action==='emicalc'){
      const P=Number($('#emi-principal').value),annual=Number($('#emi-rate').value),years=Number($('#emi-years').value);if(P>0&&years>0){const r=annual/1200,n=years*12;const emi=r===0?P/n:P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);$('#emi-result').innerHTML=`₹ ${Math.round(emi).toLocaleString('en-IN')} <small>${t('monthly EMI · illustration only','मासिक EMI · केवल उदाहरण')}</small>`;}else $('#emi-result').textContent=t('Enter valid values','सही मान भरें');
    }
    else if(action==='printmoney'){printMoneyMap();}
    else if(action==='printactivity'){printActivity(levels.find(x=>x.id===state.active));}
    else if(action==='printchecklist'){printHTML('Household checklist',`<ol>${levels.map(l=>`<li><b>${escapeHTML(l.title)}</b> — ${escapeHTML(l.both)}</li>`).join('')}</ol>`);}
    else if(action==='startactivity'){showActivity(levels.find(x=>x.id===state.active));}
  }
  app.addEventListener('click',e=>{
    const levelBtn=e.target.closest('[data-level]');if(levelBtn){openLevel(levelBtn.dataset.level);return;}
    const tabBtn=e.target.closest('[data-tab]');if(tabBtn){e.preventDefault();state.tab=tabBtn.dataset.tab;renderLevel();document.querySelector('#lesson-area')?.scrollIntoView({block:'start',behavior:'smooth'});return;}
    const act=e.target.closest('[data-action]');if(act){doAction(act.dataset.action);return;}
    const book=e.target.closest('[data-book]');if(book){const key=book.dataset.book;state.bookmarks=state.bookmarks.includes(key)?state.bookmarks.filter(x=>x!==key):[...state.bookmarks,key];save();renderLevel();return;}
    const answer=e.target.closest('[data-answer]');if(answer){const l=levels.find(x=>x.id===state.active),q=state.quiz[l.id]||{index:0,answers:[]};if(q.answers[q.index]===undefined){q.answers[q.index]=Number(answer.dataset.answer);state.quiz[l.id]=q;save();renderLevel();}return;}
    const close=e.target.closest('[data-close-modal]');if(close){e.target.closest('.modal-backdrop')?.remove();return;}
    const cardHead=e.target.closest('.lesson-card-head');if(cardHead){cardHead.closest('.lesson-card')?.classList.toggle('expanded');return;}
    const saved=e.target.closest('[data-open-card]');if(saved){openLevel(saved.dataset.openCard);setTimeout(()=>{const card=[...app.querySelectorAll('.lesson-card')].find(x=>x.dataset.card?.endsWith(saved.dataset.cardTitle));card?.classList.add('expanded');card?.scrollIntoView({behavior:'smooth'});},150);return;}
    const printTpl=e.target.closest('[data-print-template]');if(printTpl){const type=printTpl.dataset.printTemplate;const rows=type==='Money Map'?['Income sources','Fixed expenses','Variable expenses','Loans / EMI / due date','Policies / nominees','Accounts / record location','Who knows what']:type==='Decision Log'?['Date','Purchase','Amount','Alternatives','Decision / reason','Who agreed','Review date']:type==='Goal Timeline'?['Goal','Cost today','Target year','Inflation assumption','Monthly amount','Priority']:['Institutions','Assets / liabilities','Nominees','Document locations','Claim contacts','Will location'];printHTML(type,`<table><tbody>${rows.map(x=>`<tr><th>${x}</th><td style="height:44px"></td></tr>`).join('')}</tbody></table>`);}
  });
  app.addEventListener('change',e=>{
    const lang=e.target.closest('#language');if(lang){state.lang=lang.value;save();state.active?renderLevel():renderHome();return;}
    const done=e.target.closest('[data-done]');if(done){const key=done.dataset.done;state.done=done.checked?[...new Set([...state.done,key])]:state.done.filter(x=>x!==key);save();renderLevel();return;}
    const green=e.target.closest('[data-green]');if(green){state.greenDone=state.greenDone||{};const id=Number(green.dataset.green),idx=Number(green.dataset.index);state.greenDone[id]=state.greenDone[id]||[];state.greenDone[id]=green.checked?[...new Set([...state.greenDone[id],idx])]:state.greenDone[id].filter(x=>x!==idx);save();return;}
    const activity=e.target.closest('[data-activity]');if(activity){state.activities=state.activities||[];const id=Number(activity.dataset.activity);state.activities=activity.checked?[...new Set([...state.activities,id])]:state.activities.filter(x=>x!==id);save();return;}
    const allgreen=e.target.closest('[data-allgreen]');if(allgreen){state.greenDoneAll=state.greenDoneAll||[];const id=Number(allgreen.dataset.allgreen);state.greenDoneAll=allgreen.checked?[...new Set([...state.greenDoneAll,id])]:state.greenDoneAll.filter(x=>x!==id);save();return;}
  });
  document.body.classList.remove('dark-mode');state.dark=false;
  if(state.safe){safePage();}else if(state.active){renderLevel();}else{renderHome();}
})();
